using System.Globalization;
using System.Security.Cryptography;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.AspNetCore.TestHost;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.DependencyInjection.Extensions;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Time.Testing;

namespace Apogeu.Security.Tests.Support;

/// <summary>
/// The real Host in memory (WebApplicationFactory) on real PostgreSQL and Redis, configured only with values generated by
/// the test (ADR-0014: no real credential anywhere): two demo API keys (rotation), the session signing key, the game base
/// URL and the demo operator's frame ancestors. The clock is a <see cref="FakeTimeProvider"/> started at the real current
/// time truncated to a whole millisecond (the REST contract serializes timestamps with millisecond precision, SPEC-0006),
/// so tokens validated against the wall clock stay valid while the tests move the fake clock forward and expected
/// expirations compare exactly with the serialized ones.
/// Hosted services of the other modules are removed (they would run their own work); the Operators module's stay, so the
/// Development seed of the demo operator happens through the real path, and so do the Rounds module's when the test uses
/// the real rounds hub (<see cref="SecurityHostOptions.WithRoundsHub"/>).
/// </summary>
internal sealed class SecurityHost : IAsyncDisposable
{
    public static readonly Uri BaseAddress = new("https://api.apogeu.test");
    public static readonly Uri GameBaseUrl = new("https://game.apogeu.test");
    public const string FrameAncestor = "https://casino.apogeu.test";

    private readonly WebApplicationFactory<Program> _factory;

    private SecurityHost(WebApplicationFactory<Program> factory, FakeTimeProvider clock, TestApiKey primaryKey, TestApiKey secondaryKey, string sessionSigningKey)
    {
        _factory = factory;
        Clock = clock;
        PrimaryKey = primaryKey;
        SecondaryKey = secondaryKey;
        SessionSigningKey = sessionSigningKey;
    }

    public FakeTimeProvider Clock { get; }

    /// <summary>First active key of the demo operator.</summary>
    public TestApiKey PrimaryKey { get; }

    /// <summary>Second active key of the demo operator (two keys during a rotation, ADR-0014).</summary>
    public TestApiKey SecondaryKey { get; }

    /// <summary>Base64 of the key that signs player sessions (a secret: must never reach the logs).</summary>
    public string SessionSigningKey { get; }

    public TestServer Server => _factory.Server;

    public static async Task<SecurityHost> StartAsync(
        string postgresServerConnectionString,
        string redisConnectionString,
        SecurityHostOptions options,
        CancellationToken cancellationToken)
    {
        var database = await TestDatabase.CreateAsync(postgresServerConnectionString, cancellationToken).ConfigureAwait(false);
        var clock = new FakeTimeProvider(DateTimeOffset.FromUnixTimeMilliseconds(DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()));
        var primary = TestApiKey.Generate();
        var secondary = TestApiKey.Generate();
        var signingKey = Convert.ToBase64String(RandomNumberGenerator.GetBytes(32));

        var factory = new WebApplicationFactory<Program>().WithWebHostBuilder(host => Configure(host, options, database, redisConnectionString, clock, primary, secondary, signingKey));

        try
        {
            // Starts the host now (migrations and the Development seed run here), not inside the first measured call.
            _ = factory.Server;
        }
        catch
        {
            await factory.DisposeAsync().ConfigureAwait(false);
            throw;
        }

        return new SecurityHost(factory, clock, primary, secondary, signingKey);
    }

    private static void Configure(
        IWebHostBuilder host,
        SecurityHostOptions options,
        string database,
        string redisConnectionString,
        FakeTimeProvider clock,
        TestApiKey primary,
        TestApiKey secondary,
        string signingKey)
    {
        host.UseEnvironment(options.Environment);
        host.UseSetting("ConnectionStrings:apogeu", database);
        host.UseSetting("ConnectionStrings:redis", redisConnectionString);
        host.UseSetting("Operators:GameBaseUrl", GameBaseUrl.ToString());
        host.UseSetting("Operators:Demo:ApiKeys:0:Id", primary.Id);
        host.UseSetting("Operators:Demo:ApiKeys:0:Secret", primary.Secret);
        host.UseSetting("Operators:Demo:ApiKeys:1:Id", secondary.Id);
        host.UseSetting("Operators:Demo:ApiKeys:1:Secret", secondary.Secret);
        host.UseSetting("Operators:Demo:FrameAncestors:0", FrameAncestor);
        host.UseSetting("Security:PlayerSession:SigningKey", signingKey);
        if (options.BackofficeAuthority is not null)
        {
            host.UseSetting("Security:Backoffice:Authority", options.BackofficeAuthority.ToString());
            host.UseSetting("Security:Backoffice:Audience", options.BackofficeAudience);
            host.UseSetting("Security:Backoffice:RequireHttpsMetadata", bool.FalseString);
        }

        if (options.LogCapture is { } capture)
        {
            host.ConfigureLogging(logging =>
            {
                logging.AddProvider(capture);
                logging.AddFilter("Apogeu", LogLevel.Trace);
            });
        }

        host.ConfigureTestServices(services =>
        {
            services.Replace(ServiceDescriptor.Singleton<TimeProvider>(clock));
            var otherModules = services
                .Where(d => d.ServiceType == typeof(IHostedService)
                    && d.ImplementationType?.Assembly.GetName().Name is { } assembly
                    && assembly.StartsWith("Apogeu.", StringComparison.Ordinal)
                    && !assembly.StartsWith("Apogeu.Operators.", StringComparison.Ordinal)
                    && !(options.WithRoundsHub && assembly.StartsWith("Apogeu.Rounds.", StringComparison.Ordinal)))
                .ToList();
            foreach (var descriptor in otherModules)
            {
                services.Remove(descriptor);
            }
        });
    }

    /// <summary>A client on <see cref="BaseAddress"/> (HTTPS and a non-localhost name, so HSTS applies), without redirects.</summary>
    public HttpClient CreateClient() =>
        _factory.CreateClient(new WebApplicationFactoryClientOptions { BaseAddress = BaseAddress, AllowAutoRedirect = false });

    public long UnixNow() => Clock.GetUtcNow().ToUnixTimeSeconds();

    public string UnixNowText() => UnixNow().ToString(CultureInfo.InvariantCulture);

    public ValueTask DisposeAsync() => _factory.DisposeAsync();
}
